  const [state, setState] = useState<AppState>({ 
    people: [], tasks: [], particularities: [], serviceCategories: DEFAULT_CATEGORIES, userRole: 'master' 
  });

  const persistState = async (newState: AppState) => {
    setState(newState);
    await apiService.saveState(newState);
  };

  useEffect(() => {
    apiService.loadState().then(saved => saved && setState(saved));
