import { supabaseService } from './services/supabase';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services' | 'particularities'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const isSavingRef = useRef(false);

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('app-theme');
    return (saved as 'light' | 'dark') || 'light';
  });

  const [state, setState] = useState<AppState>({ 
    people: [], 
    tasks: [], 
    particularities: [],
    serviceCategories: DEFAULT_CATEGORIES,
    userRole: 'master',
    updatedAt: 0
  });

  // Carrega dados iniciais e protege contra sobrescritas de saves em curso
  const loadData = useCallback(async (showLoading = false) => {
    if (isSavingRef.current) return; // Não carrega se estiver salvando algo novo

    if (showLoading) setIsSyncing(true);
    try {
      const bestState = await apiService.loadState();
      if (bestState) {
        setState(prev => {
          // Só aceita o estado externo se ele for mais novo que o que o usuário tem agora
          if (bestState.updatedAt > prev.updatedAt) {
            return { ...bestState, userRole: prev.userRole };
          }
          return prev;
        });
      }
    } catch (error) {
      console.error("Erro ao carregar dados:", error);
    } finally {
      if (showLoading) setTimeout(() => setIsSyncing(false), 600);
    }
  }, []);

  // Função centralizada para persistir alterações
  // Recebe uma função transformadora para garantir que o estado seja o mais atual
  const updateAndPersist = useCallback(async (updater: (prevState: AppState) => AppState) => {
    isSavingRef.current = true;
    setIsSyncing(true);

    try {
      let nextState: AppState | null = null;

      // 1. Atualiza a UI imediatamente com o novo timestamp
      setState(prev => {
        nextState = updater(prev);
        nextState.updatedAt = Date.now();
        return nextState;
      });

      // 2. Persiste no Storage e Supabase
      if (nextState) {
        await apiService.saveState(nextState);
      }
    } catch (e) {
      console.error("Erro na persistência crítica:", e);
    } finally {
      isSavingRef.current = false;
      setTimeout(() => setIsSyncing(false), 500);
    }
  }, []);

  // Monitoramento em Tempo Real
  useEffect(() => {
    if (isLoggedIn) {
      loadData(true).then(() => setIsLoading(false));

      const unsubscribe = supabaseService.subscribeToChanges((remoteState) => {
        // Ignora atualizações remotas se estivermos salvando ou se o remoto for antigo
        if (isSavingRef.current) return;

        setState(prev => {
          if (remoteState.updatedAt > prev.updatedAt) {
            return { ...prev, ...remoteState, userRole: prev.userRole };
          }
          return prev;
        });
      });

      return () => unsubscribe();
    } else {
      setIsLoading(false);
    }
  }, [isLoggedIn, loadData]);

  // Gerenciamento de Tema
  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
    localStorage.setItem('app-theme', theme);
  }, [theme]);

  const handleLogin = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  // Actions refatoradas para usar updateAndPersist com callbacks funcionais
  const addPerson = (person: Person) => updateAndPersist(prev => ({
    ...prev,
    people: [...prev.people, person]
  }));

  const removePerson = (id: string) => updateAndPersist(prev => ({
    ...prev,
    people: prev.people.filter(p => p.id !== id),
    tasks: prev.tasks.filter(t => t.personId !== id),
    particularities: prev.particularities.filter(p => p.personId !== id)
  }));

  const addTask = (task: Task) => updateAndPersist(prev => ({
    ...prev,
    tasks: [...prev.tasks, task]
  }));

  const editTask = (updatedTask: Task) => updateAndPersist(prev => ({
    ...prev,
    tasks: prev.tasks.map(t => t.id === updatedTask.id ? updatedTask : t)
  }));

  const removeTask = (id: string) => updateAndPersist(prev => ({
    ...prev,
    tasks: prev.tasks.filter(t => t.id !== id)
  }));

  const addParticularity = (p: Particularity) => updateAndPersist(prev => ({
    ...prev,
    particularities: [...prev.particularities, p]
  }));

  const removeParticularity = (id: string) => updateAndPersist(prev => ({
    ...prev,
    particularities: prev.particularities.filter(p => p.id !== id)
  }));

  const addServiceCategory = (cat: ServiceCategory) => updateAndPersist(prev => ({
    ...prev,
    serviceCategories: [...prev.serviceCategories, cat]
  }));

  const removeServiceCategory = (id: string) => updateAndPersist(prev => ({
    ...prev,
    serviceCategories: prev.serviceCategories.filter(c => c.id !== id),
    tasks: prev.tasks.filter(t => t.serviceCategoryId !== id)
  }));

  const importState = (imported: AppState) => updateAndPersist(() => imported);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center p-6">
        <div className="w-16 h-16 border-4 border-blue-600/20 border-t-blue-600 rounded-full animate-spin"></div>
        <p className="mt-6 font-black text-[10px] text-slate-400 dark:text-slate-600 uppercase tracking-[0.3em] animate-pulse">Sincronização Ativa</p>
      </div>
    );
  }

  if (!isLoggedIn) return <Login onLogin={handleLogin} />;

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 transition-colors">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.userRole}
        onRoleChange={(role) => setState(prev => ({...prev, userRole: role}))}
        onLogout={handleLogout}
        theme={theme}
        toggleTheme={toggleTheme}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto custom-scrollbar">
        <header className="mb-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="space-y-1">
            <h1 className="text-4xl font-black text-slate-800 dark:text-slate-100 capitalize tracking-tighter">{activeTab}</h1>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest opacity-60">Segurança de Dados • Tempo Real</p>
          </div>

          <div className="flex items-center gap-3">
            {isSyncing ? (
               <div className="flex items-center gap-2 px-5 py-2.5 bg-blue-600 text-white text-[10px] font-black rounded-2xl shadow-lg shadow-blue-200 dark:shadow-none animate-pulse">
                 <Icons.Refresh /> PROTEGENDO DADOS...
               </div>
            ) : (
              <div className="flex items-center gap-2 px-5 py-2.5 bg-emerald-500 text-white text-[10px] font-black rounded-2xl shadow-lg shadow-emerald-200 dark:shadow-none">
                 ✓ AMBIENTE SEGURO
               </div>
            )}
            <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${state.userRole === 'master' ? 'bg-indigo-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400'}`}>
              PERFIL {state.userRole}
            </div>
          </div>
        </header>

        <div className="fade-in">
          {activeTab === 'dashboard' && <Dashboard state={state} onRefresh={() => loadData(true)} />}
          {activeTab === 'people' && <PeopleManager people={state.people} onAdd={addPerson} onRemove={removePerson} />}
          {activeTab === 'logs' && (
            <DailyLog 
              tasks={state.tasks} 
              people={state.people} 
              categories={state.serviceCategories}
              onAddTask={addTask} 
              onEditTask={editTask}
              onRemoveTask={removeTask}
              userRole={state.userRole}
              onRefresh={() => loadData(true)}
            />
          )}
          {activeTab === 'particularities' && (
            <ParticularityManager 
              particularities={state.particularities}
              people={state.people}
              onAdd={addParticularity}
              onRemove={removeParticularity}
            />
          )}
          {activeTab === 'services' && (
            <ServiceManager 
              categories={state.serviceCategories} 
              onAdd={addServiceCategory} 
              onRemove={removeServiceCategory} 
              state={state}
              onImport={importState}
            />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;
